function pointsFor(p, s, g) {
  return g * (p.passYd / s.passYds + p.passTd * s.passTd - p.ints * s.intPen +
    p.rushYd / s.rushYds + p.rushTd * s.rushTd + p.recYd / s.recYds +
    p.recTd * s.recTd + p.rec * s.ppr);
}

function buildStarters(scored, teams, roster) {
  const byPos = {};
  POS.forEach((q) => { byPos[q] = scored.filter((p) => p.pos === q).sort((a, b) => b.pts - a.pts); });
  const st = { QB: [], RB: [], WR: [], TE: [] };
  const used = new Set();
  POS.forEach((q) => {
    byPos[q].slice(0, (roster[q] || 0) * teams).forEach((p) => { st[q].push(p); used.add(p.id); });
  });
  const take = (elig, n) => scored.filter((p) => elig.includes(p.pos) && !used.has(p.id))
    .sort((a, b) => b.pts - a.pts).slice(0, n)
    .forEach((p) => { st[p.pos].push(p); used.add(p.id); });
  take(["RB", "WR", "TE"], (roster.FLEX || 0) * teams);
  take(["QB", "RB", "WR", "TE"], (roster.SUPERFLEX || 0) * teams);
  const counts = {};
  POS.forEach((q) => { counts[q] = st[q].length; });
  return { counts };
}

function replacementLevels(scored, teams, roster, bench) {
  const totalStarters = POS.reduce((a, q) => a + (roster[q] || 0), 0) + (roster.FLEX || 0) + (roster.SUPERFLEX || 0);
  const K = Math.min(Math.max(Math.round(totalStarters + bench), 1), 14);
  const capped = K < Math.round(totalStarters + bench);
  const profileTeams = teams <= 11 ? 10 : 12;
  const sf = roster.SUPERFLEX > 0 ? 1 : 0;
  const profile = ROSTER_COMP[`${profileTeams}_${sf}`]?.[K];
  const lv = {};
  POS.forEach((q) => {
    const pool = scored.filter((p) => p.pos === q).sort((a, b) => b.pts - a.pts);
    if (!profile || pool.length === 0) { lv[q] = 0; return; }
    const leagueTotal = teams * profile[POS_LETTER[q]];
    const idx = Math.min(Math.round(leagueTotal), pool.length - 1);
    lv[q] = pool[idx]?.pts ?? pool[pool.length - 1].pts;
  });
  return { lv, capped, K };
}

function scoringBucket(roster, ppr) {
  if (roster.SUPERFLEX > 0) return "superflex_ppr";
  return ppr >= 0.75 ? "standard_ppr" : "half_ppr";
}
function cappedStateKey(myCounts, round) {
  const key = POS.map((p) => Math.min(myCounts[p] || 0, STATE_CAPS[p])).join("");
  return `${round}|${key}`;
}
function lookupBoosts(bucket, myCounts, round) {
  const table = BOOSTS[bucket];
  if (!table) return null;
  return table[cappedStateKey(myCounts, round)] || null;
}

// ---- season simulation: real week-by-week variance + injury-absence, not just season totals
function gaussianRandom() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function sampleAbsenceWeeks(expG, totalWeeks) {
  // a single contiguous absence block, not scattered random misses - real injuries take
  // out consecutive weeks, not one week here and there
  const missed = Math.max(0, Math.round(totalWeeks - expG));
  if (missed === 0) return new Set();
  const maxStart = Math.max(1, totalWeeks - missed + 1);
  const start = 1 + Math.floor(Math.random() * maxStart);
  const out = new Set();
  for (let w = start; w < start + missed && w <= totalWeeks; w++) out.add(w);
  return out;
}
function optimalWeekLineup(weekPlayers, roster) {
  const byPos = { QB: [], RB: [], WR: [], TE: [] };
  weekPlayers.forEach((p) => byPos[p.pos].push(p));
  POS.forEach((q) => byPos[q].sort((a, b) => b.pts - a.pts));
  const used = new Set();
  let total = 0;
  POS.forEach((q) => {
    byPos[q].slice(0, roster[q] || 0).forEach((p) => { total += p.pts; used.add(p.id); });
  });
  let flexPool = [];
  ["RB", "WR", "TE"].forEach((q) => { flexPool.push(...byPos[q].filter((p) => !used.has(p.id))); });
  flexPool.sort((a, b) => b.pts - a.pts);
  flexPool.slice(0, roster.FLEX || 0).forEach((p) => { total += p.pts; used.add(p.id); });
  if (roster.SUPERFLEX > 0) {
    let sfPool = [];
    POS.forEach((q) => { sfPool.push(...byPos[q].filter((p) => !used.has(p.id))); });
    sfPool.sort((a, b) => b.pts - a.pts);
    sfPool.slice(0, roster.SUPERFLEX).forEach((p) => { total += p.pts; });
  }
  return total;
}
function simulateTeamSeason(playerIds, allScored, scoring, roster, totalWeeks = 17) {
  const players = playerIds.map((id) => allScored.find((p) => p.id === id)).filter(Boolean);
  const perGame = players.map((p) => ({
    id: p.id, pos: p.pos,
    rate: pointsFor(p, scoring, 1),
    absent: sampleAbsenceWeeks(p.expG, totalWeeks),
    cv: WEEKLY_CV[p.pos] || 0.55,
  }));
  const weeklyTotals = [];
  for (let w = 1; w <= totalWeeks; w++) {
    const weekPlayers = perGame.filter((p) => !p.absent.has(w)).map((p) => {
      const z = gaussianRandom();
      const val = Math.max(0, p.rate * (1 + z * p.cv));
      return { id: p.id, pos: p.pos, pts: val };
    });
    weeklyTotals.push(optimalWeekLineup(weekPlayers, roster));
  }
  return weeklyTotals;
}
